(()=>{'use strict';const {$,$$,esc:E}=Q;let mediaSerial=0;const fullSource='https://www.mp3quran.net/api/v3/reciters?language=eng&rewaya=1';const valid=url=>{try{const u=new URL(url);return u.protocol==='https:'&&/(^|\.)(islamic\.network|mp3quran\.net)$/.test(u.hostname);}catch{return false;}};
const sourceClips=[{surah:25,title:'Muhammad Al-Luhaidan | 25:61-77',type:'soundcloud',url:'https://soundcloud.com/theclearquran/surah-al-furqan-61-77-sheikh-muhammad-al-luhaidan'},{surah:25,title:'Omar Hisham Al Arabi | 25:61-77',type:'soundcloud',url:'https://soundcloud.com/omarhishamalarabi/surah-al-furqan'}];
Q.recordings=async()=>{const p=Q.active;if(!p)return;const token=++mediaSerial,root=$('#recordingsPanel');root.innerHTML=`<h3>${E(Q.t('listen'))}</h3><p>${E(Q.t('fullSurah'))}</p><p class="source-label">MP3Quran.net</p><button class="btn" id="moreReciters">${E(Q.t('moreReciters'))}</button><div id="reciterResults"></div><h3>${E(Q.t('video'))}</h3><p>${E(Q.t('videoHelp'))}</p><div id="clips"></div><h3>${E(Q.t('officialVideos'))}</h3><p>${E(Q.t('generalVideos'))}</p><button class="btn" id="loadVideos">${E(Q.t('loadVideo'))}</button><div id="publisherVideos"></div>`;
const clips=[...sourceClips.filter(c=>c.surah===p.surahNo)];try{const u=new URL(p.listen);if(u.hostname==='www.youtube.com'&&/^[\w-]{11}$/.test(u.searchParams.get('v')||''))clips.push({title:p.reciters[0]+' | '+p.surahNo+':'+p.range,type:'youtube',id:u.searchParams.get('v'),url:p.listen});}catch{}$('#clips').innerHTML=clips.map((c,i)=>`<article class="media-card"><h4>${E(c.title)}</h4><button class="btn" data-embed="${i}">${E(Q.t('play'))}</button> <a href="${E(c.url)}" target="_blank" rel="noopener">${E(Q.t('source'))}</a><div class="embed-slot"></div></article>`).join('');$$('[data-embed]',root).forEach(b=>b.onclick=()=>{Q.stop();const c=clips[+b.dataset.embed],slot=$('.embed-slot',b.parentElement),f=document.createElement('iframe');f.title=c.title;f.allow='autoplay; encrypted-media; fullscreen';f.referrerPolicy='strict-origin-when-cross-origin';f.src=c.type==='youtube'?'https://www.youtube-nocookie.com/embed/'+c.id:'https://w.soundcloud.com/player/?url='+encodeURIComponent(c.url)+'&auto_play=false';slot.replaceChildren(f);b.disabled=true;});
$('#moreReciters').onclick=async()=>{const b=$('#moreReciters'),out=$('#reciterResults');b.disabled=true;out.textContent=Q.t('loading');try{const z=await Q.json(fullSource+'&sura='+p.surahNo);if(token!==mediaSerial||Q.active?.rank!==p.rank)return;const reciters=Array.isArray(z.reciters)?z.reciters:[];const rank=name=>{const n=String(name).toLowerCase();return /lohaidan|luhaidan/.test(n)?0:/yasser.*dos|dos.*yasser/.test(n)?1:/mishary|mishari/.test(n)?2:/raad|rad.*kurd/.test(n)?3:/maher/.test(n)?4:5;};reciters.sort((a,b)=>rank(a.name)-rank(b.name)||a.name.localeCompare(b.name));const tracks=reciters.flatMap(r=>(r.moshaf||[]).filter(m=>String(m.surah_list).split(',').map(Number).includes(p.surahNo)).map(m=>({name:r.name+' | '+m.name,url:String(m.server).replace(/^http:/,'https:').replace(/\/?$/,'/')+String(p.surahNo).padStart(3,'0')+'.mp3'}))).filter(r=>valid(r.url));if(!tracks.length)throw Error('No source recording for this surah');out.innerHTML=`<select class="field" id="fullReciter" aria-label="${E(Q.t('reciter'))}">${tracks.map((r,i)=>`<option value="${i}">${E(r.name)}</option>`).join('')}</select><article class="media-card"><p>${E(Q.t('fullSurah'))}</p><audio id="fullPlayer" controls preload="none"></audio><div class="control-row"><button class="btn primary" id="fullPlay">${E(Q.t('play'))}</button><button class="btn" id="fullSave">${E(Q.t('saveMedia'))}</button><a class="btn" id="fullSource" target="_blank" rel="noopener">${E(Q.t('source'))}</a></div><p id="fullStatus" role="status"></p></article>`;const selected=()=>tracks[+$('#fullReciter').value];$('#fullSource').href=selected().url;$('#fullReciter').onchange=()=>{Q.stop();$('#fullPlayer').removeAttribute('src');$('#fullSource').href=selected().url;$('#fullStatus').textContent='';};$('#fullPlay').onclick=()=>Q.play($('#fullPlayer'),selected().url);$('#fullSave').onclick=async()=>{const button=$('#fullSave'),track=selected();button.disabled=true;$('#fullStatus').textContent=Q.t('loading');try{await Q.saveMedia(track.url,p.surah+' | '+track.name);$('#fullStatus').textContent=Q.t('audioSaved');}catch(e){$('#fullStatus').textContent=Q.t('storageError')+' '+e.message;}finally{button.disabled=false;}};}catch(e){if(token===mediaSerial)Q.error(out,e);}finally{b.disabled=false;}};
$('#loadVideos').onclick=async()=>{const button=$('#loadVideos'),out=$('#publisherVideos');button.disabled=true;out.textContent=Q.t('loading');try{const [z,t]=await Promise.all([Q.json('https://www.mp3quran.net/api/v3/videos?language=eng'),Q.json('https://www.mp3quran.net/api/v3/video_types?language=eng')]);if(token!==mediaSerial)return;const types=new Map((t.video_types||[]).map(x=>[String(x.id),x.video_type])),videos=(z.videos||[]).flatMap(r=>(r.videos||[]).map(v=>({name:r.reciter_name+' | '+(types.get(String(v.video_type))||'Publisher video '+v.id),url:String(v.video_url||'').replace(/^http:/,'https:')}))).filter(v=>valid(v.url));if(!videos.length)throw Error('No videos available');out.innerHTML=`<select class="field" id="videoSelect" aria-label="${E(Q.t('video'))}">${videos.map((v,i)=>`<option value="${i}">${E(v.name)}</option>`).join('')}</select><article class="media-card"><p>${E(Q.t('generalVideos'))}</p><video id="videoPlayer" controls playsinline preload="none"></video><audio id="videoAudio" controls preload="none" hidden></audio><div class="control-row"><button class="btn" id="videoPlay">${E(Q.t('play'))}</button><button class="btn" id="videoAudioPlay">${E(Q.t('audioOnly'))}</button><button class="btn" id="videoSave">${E(Q.t('saveMedia'))}</button><a class="btn" id="videoSource" target="_blank" rel="noopener">${E(Q.t('source'))}</a></div><p id="videoStatus" role="status"></p></article>`;const selected=()=>videos[+$('#videoSelect').value];$('#videoSource').href=selected().url;$('#videoSelect').onchange=()=>{Q.stop();$('#videoSource').href=selected().url;$('#videoStatus').textContent='';};$('#videoPlay').onclick=()=>{$('#videoPlayer').hidden=false;$('#videoAudio').hidden=true;Q.play($('#videoPlayer'),selected().url);};$('#videoAudioPlay').onclick=()=>{$('#videoPlayer').hidden=true;$('#videoAudio').hidden=false;Q.play($('#videoAudio'),selected().url);};$('#videoSave').onclick=async()=>{const b=$('#videoSave'),v=selected();b.disabled=true;$('#videoStatus').textContent=Q.t('loading');try{await Q.saveMedia(v.url,v.name,'video');$('#videoStatus').textContent=Q.t('saved');}catch(e){$('#videoStatus').textContent=Q.t('storageError')+' '+e.message;}finally{b.disabled=false;}};}catch(e){Q.error(out,e);}finally{button.disabled=false;}};
};
Q.offline=async()=>{Q.stop();Q.panel(Q.t('offline'),`<p>${E(Q.t('offlineHelp'))}</p><p id="storageUse"></p><button class="btn" id="persistStorage">${E(Q.t('save'))}</button><h3>${E(Q.t('localMedia'))}</h3><p>${E(Q.t('localHelp'))}</p><input id="localMedia" type="file" accept="audio/*,video/mp4,video/webm"><div id="offlineItems"></div>`);try{const estimate=await navigator.storage?.estimate?.();if(estimate)$('#storageUse').textContent=(estimate.usage/1048576).toFixed(1)+' MB / '+(estimate.quota/1048576).toFixed(0)+' MB';}catch{}$('#persistStorage').onclick=async()=>{const ok=await navigator.storage?.persist?.().catch(()=>false);Q.toast(ok?Q.t('saved'):Q.t('cached'));};$('#localMedia').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!/^(audio\/|video\/(mp4|webm))/.test(file.type)||file.size>100*1048576){Q.toast(Q.t('localHelp'));return;}try{const url='local:'+crypto.randomUUID();await Q.idb('put','media:'+url,{url,label:file.name,type:file.type.startsWith('video')?'video':'audio',blob:file,bytes:file.size,at:Date.now()});await Q.offline();}catch{Q.toast(Q.t('storageError'));}};const target=$('#offlineItems');try{const keys=(await Q.idb('keys')).filter(k=>k.startsWith('media:')||k.startsWith('reading:'));if(!keys.length){target.textContent=Q.t('noSaved');return;}const records=await Promise.all(keys.map(async key=>({key,value:await Q.idb('get',key)})));target.innerHTML=records.map(({key,value:v},i)=>`<article class="offline-card"><h4>${E(v.label||PName(v.rank)+' '+v.range+' | '+v.lang)}</h4><p>${E(new Date(v.at).toLocaleString(Q.lang))}${v.bytes?' | '+(v.bytes/1048576).toFixed(2)+' MB':''}</p><div class="control-row"><button class="btn" data-off-open="${i}">${E(Q.t('play'))} / ${E(Q.t('open'))}</button>${v.type==='video'?`<button class="btn" data-audio-only="${i}">${E(Q.t('audioOnly'))}</button>`:''}${v.blob?`<button class="btn" data-export-media="${i}">${E(Q.t('download'))}</button>`:''}<button class="btn" data-off-remove="${i}">${E(Q.t('remove'))}</button></div><div class="offline-player"></div></article>`).join('');async function open(i,audioOnly=false){const v=records[i].value;if(!v.blob){Q.lang=v.lang;Q.language();$('#utilityDialog').close();Q.open(v.rank);return;}Q.stop();const box=$$('.offline-player',target)[i],el=document.createElement(v.type==='video'&&!audioOnly?'video':'audio');el.controls=true;el.playsInline=true;el.style.width='100%';el.style.maxHeight='420px';box.replaceChildren(el);await Q.play(el,v.url);}$$('[data-off-open]',target).forEach(b=>b.onclick=()=>open(+b.dataset.offOpen));$$('[data-audio-only]',target).forEach(b=>b.onclick=()=>open(+b.dataset.audioOnly,true));$$('[data-off-remove]',target).forEach(b=>b.onclick=async()=>{Q.stop();await Q.idb('delete',records[+b.dataset.offRemove].key);Q.offline();});$$('[data-export-media]',target).forEach(b=>b.onclick=()=>{const v=records[+b.dataset.exportMedia].value;Q.download(v.blob,v.label.replace(/[^\w. -]/g,'_')+(/\.(mp3|mp4|webm|wav|ogg|m4a)$/i.test(v.label)?'':v.blob.type.includes('webm')?'.webm':v.blob.type.includes('wav')?'.wav':v.type==='video'?'.mp4':'.mp3'));});}catch{target.textContent=Q.t('storageError');}};function PName(rank){return window.PASSAGES.find(p=>p.rank===rank)?.surah||'Quran';}$('#offlineOpen').onclick=Q.offline;})();
